css:
body { 
font-family: 'Times New Roman', Times, serif; 
font-size: 10pt; 
}
.voucher-container { width: 100%; margin: 0 auto; border: 1px solid #000; padding: 15px; }
.header-section { text-align: center; margin-bottom: 10px; }
.header-section h3 { margin: 5px 0; }
.header-section small { display: block; margin-top: -5px; }


.main-table { 
width: 100%; 
border-collapse: collapse; 
margin-bottom: 0px; 
}

.details-table { 
margin-top: -1px; 
margin-bottom: 15px; 
}

.main-table th, .main-table td { 
border: 1px solid #000; 
padding: 5px; 
vertical-align: top; 
}


.accounts-header th {
text-align: center;
font-weight: bold;
background-color: #f2f2f2;
}

.jv-top-row td {
border-bottom: none;
}

.jv-bottom-row td {
border-top: none;
}

.jv-top-row .particulars-cell {
border-bottom: 1px solid #000 !important; 
}


.footer-section { margin-top: 20px; }
.left-align { text-align: left; }
.right-align { text-align: right; }
.center-align { text-align: center; }
.no-border { border: none !important; }
.underline { text-decoration: underline; }
